    // from it, but a style written here and read back by an older build should
    // still land on the right weight rather than the 2px default.
    annotationStyle.weight = annotationStyle.lineWeightPt * ELEV_PT_TO_PX;
    // A style stored before the dash rhythm was a setting has no dashPt. It lands
    // on the default rather than on whatever the old derived-from-weight pattern
    // happened to be, deliberately: that pattern is the reported bug.
    annotationStyle.dashPt = _snapDashPt(annotationStyle.dashPt);
    // Wireframe letter. A style stored before these existed picks up the defaults.
    const _wfs = parseFloat(annotationStyle.wfSize);
    annotationStyle.wfSize = (isFinite(_wfs) && _wfs >= 9 && _wfs <= 48) ? _wfs : ELEV_WF_SIZE_DEFAULT;
    annotationStyle.wfFont = _fontToken(annotationStyle.wfFont, 'serif');
