// =========================================================================
// INITIALIZATION & NAVIGATION
// =========================================================================
function initMasterApp() {
    document.getElementById('g_date').valueAsDate = new Date();
    _helpDotInit();
    _elevGuideGroupsInit();
    // Not under a test harness: a modal appearing on its own at boot would land in the
    // middle of whatever a headless check is doing (the autosave-warning flake again).
    renderNavTabs();
    selectDashRow(0); 
    populateDashPushSelector();
    updateDimFontSize();
    loadBundledLibrary().then(() => {
        // After the bundled library is loaded, restore any swatches the user
        // previously uploaded. Saved entries override bundled ones with the
        // same code, matching the precedence rule of live syncDashLibraryFolder.
        restoreCustomLibraryFromStorage();
    });
    _initFontSelects();    // fill every static font picker from FRAME_FONT_LIBRARY
    loadAnnotationStyle(); // restore saved annotation color/weight/dash defaults
    loadDimVisibility();   // restore saved per-element dimension hide flags
    loadSvgFrameMode();    // restore SVG frame export mode (texture/autocolor)
    loadSnapPref();        // restore snap-to-align on/off preference
    loadDimSnapPref();     // restore dimension-drag snap preference
    seedHangBaseboardInputs(); // hang height + baseboard, derived from stored inches
    seedDeckPlanOrderInput();  // floorplan page order, a display of editorialContent.planOrder
    _dsIncludeInit();          // include-page checkboxes: one delegated listener, then restore
    _initElevSidebarTab();     // Art / Context / Glass, restored from last session
    _applyPersonShade();   // figure shade: wall figure, Settings preview + swatches

    // Custom measured-line tool: wall click (capture phase so it runs before
    // frame handlers when the tool is active), 'M' shortcut, Delete to remove.
    const wallEl = document.getElementById('wall');
    if (wallEl) {
        wallEl.addEventListener('mousedown', function (e) {
            if (lineToolActive) { handleLineToolClick(e); return; }
            // Click on empty space (not a dim/line) deselects.
            if ((selectedCustomLine || selectedDimId) && !e.target.closest('.custom-line') && !e.target.closest('.arch-dim')) {
                selectedCustomLine = null;
                selectedDimId = null;
                drawElevAll();
            }
        }, true);
        // Live anchor-point indicator: blue dot snaps to the nearest anchor
        // while the measure tool is active.
        wallEl.addEventListener('mousemove', function (e) {
            if (!lineToolActive) return;
            updateAnchorHoverDot(e);
        });
        wallEl.addEventListener('mouseleave', function () {
            const d = document.getElementById('anchor-hover-dot');
            if (d) d.style.display = 'none';
        });
        // Wheel scaling for the client-elevation guide, ONLY while placing it. Not
        // passive, because it has to preventDefault or the workspace scrolls under the
        // gesture — and a passive listener is not allowed to.
        wallEl.addEventListener('wheel', function (e) {
            if (typeof _ulPlacing !== 'undefined' && _ulPlacing) _ulWheelScale(e);
        }, { passive: false });
    }
    document.addEventListener('keydown', function (e) {
        const typing = /^(INPUT|TEXTAREA|SELECT)$/.test((e.target && e.target.tagName) || '');
        if (typing) return;
        // Only act when the elevation view is visible.
        const elevVisible = (() => { const v = document.getElementById('view-elevation'); return v && getComputedStyle(v).display !== 'none'; })();
        if (!elevVisible) return;
        if ((e.key === 'm' || e.key === 'M') && !e.ctrlKey && !e.metaKey) {
            toggleLineTool();
        } else if ((e.key === 'c' || e.key === 'C') && !e.ctrlKey && !e.metaKey) {
            // Not Ctrl/Cmd — that is copy, and stealing it here would break it on the
            // one view where a letter shortcut and a clipboard shortcut share a key.
            toggleContextTool();
        } else if ((e.key === 'Delete' || e.key === 'Backspace') && _ctxSelectedCount()) {
            // DELETE THE SELECTED CONTEXT BLOCKS. Ahead of the custom-line branch below
            // because a block selection is the more recent, more visible thing — and
            // ahead of anything that could swallow the key. Nothing selected means this
            // clause doesn't match at all, so Delete keeps its old meaning elsewhere.
            e.preventDefault();
            deleteSelectedContextBlocks();
        } else if ((e.key === 'a' || e.key === 'A') && (e.ctrlKey || e.metaKey)
                   && _elevSidebarTab === 'context') {
            // Select-all, scoped to the Context tab so it cannot hijack Ctrl+A while
            // someone is working on frames. With this, clearing a traced wall is
            // Ctrl+A then Delete.
            e.preventDefault();
            selectAllContextBlocks();
        } else if (_ctxSelectedCount() && e.key.indexOf('Arrow') === 0 && !_ulPlacing) {
            // NUDGE the selected blocks, the whole selection together — the same gesture
            // that moves a frame. Shift refines to a tenth of the snap step, matching
            // every other precision path here (ELEV_FINE_FACTOR).
            e.preventDefault();
            nudgeSelectedContextBlocks(e.key, e.shiftKey);
        } else if (_ulPlacing && e.key.indexOf('Arrow') === 0) {
            // Placing owns the arrows while it is on. Ahead of the custom-line nudge
            // below, because you cannot be doing both.
            if (_ulArrowNudge(e)) e.preventDefault();
        } else if ((e.key === 'Delete' || e.key === 'Backspace') && selectedCustomLine) {
            e.preventDefault();
            deleteCustomLine(selectedCustomLine);
        } else if (selectedCustomLine && e.key.indexOf('Arrow') === 0) {
            // Nudge the selected custom line's perpendicular offset.
            e.preventDefault();
            const L = getElevCustomLines().find(l => l.id === selectedCustomLine);
            if (L) {
                const stepIn = (e.shiftKey ? 5 : 1); // inches per press
                if (L.type === 'h') {
                    if (e.key === 'ArrowUp') L.off = (L.off || 0) + stepIn;
                    else if (e.key === 'ArrowDown') L.off = (L.off || 0) - stepIn;
                } else {
                    if (e.key === 'ArrowRight') L.off = (L.off || 0) + stepIn;
                    else if (e.key === 'ArrowLeft') L.off = (L.off || 0) - stepIn;
                }
                if (typeof pushHistory === 'function') pushHistory();
                drawElevAll();
            }
        } else if (e.key === 'Escape' && (lineToolActive || lineToolFirstPt || selectedCustomLine
                   || selectedDimId || contextToolActive || _ulCalibrateActive || _ulPlacing)) {
            lineToolFirstPt = null;
            lineToolFirstAnchor = null;
            selectedCustomLine = null;
            selectedDimId = null;
            // Every wall mode gets its exit here, or the one you are in is a trap. Most
            // specific first: calibrating is entered FROM placing, so Escape backs out
            // one step at a time rather than dumping both.
            if (_ulCalibrateActive) _ulCancelCalibrate();
            else if (_ulPlacing) togglePlaceUnderlay(false);
            else if (contextToolActive) toggleContextTool(false);
            else if (lineToolActive) toggleLineTool(false);
            else drawElevAll();
        }
    });
    
    document.addEventListener('click', function(event) {
        const container = document.getElementById('customSwatchContainer');
        const sList = document.getElementById('swatchDropdownList');
        if (container && !container.contains(event.target)) {
            if (sList && sList.style.display === 'block') { sList.style.display = 'none'; restoreDashThumbnail(); }
        }
        const bList = document.getElementById('bulkDropdownList');
        const bBtn = document.getElementById('bulkImportBtn');
        if (bList && bList.style.display === 'block') {
            if (bBtn && !bBtn.contains(event.target) && !bList.contains(event.target)) {
                bList.style.display = 'none';
            }
        }
    });

    // Auto-select content of number inputs on focus. Without this, clicking into
    // a field with an existing value (like "0" or "3") and typing causes the new
    // digits to be appended ("01", "33") instead of replacing — feels broken.
    // Scoped to number inputs only so text fields keep cursor-position focus behavior.
    document.addEventListener('focusin', function(event) {
        if (event.target && event.target.tagName === 'INPUT' && event.target.type === 'number') {
            // Defer the select() to next tick. Browsers sometimes ignore select()
            // called inside the focus event itself.
            setTimeout(() => { try { event.target.select(); } catch (e) {} }, 0);
        }
    });

    // Wire the Library Sync modal's drag-and-drop zone. Idempotent.
    initLibraryDropZone();
}

// Pull the bundled library manifest at startup. The manifest is generated by
// the GitHub Action in .github/workflows/build-library-manifest.yml, which
// scans the library/ folder on every push and writes library-manifest.json.
//
// The manifest format is a flat array of:
//   { vendor: "Larson-Juhl", collection: "Asbury", code: "L100ABC", width: 1.25, path: "library/Larson-Juhl/Asbury/L100ABC_1.25.png" }
//
// On 404 (no manifest yet), we fail silently so the app still works for users
// who only ever sync local folders.
async function loadBundledLibrary() {
    try {
        const res = await fetch('library-manifest.json', { cache: 'no-cache' });
        if (!res.ok) return; // no manifest published yet — that's fine
        const items = await res.json();
        if (!Array.isArray(items) || items.length === 0) return;
        items.forEach(it => {
            if (!it.vendor || !it.collection || !it.code || !it.path) return;
            if (!dashLocalLibrary[it.vendor]) dashLocalLibrary[it.vendor] = {};
            if (!dashLocalLibrary[it.vendor][it.collection]) dashLocalLibrary[it.vendor][it.collection] = [];
            // Skip if a duplicate code is already present (manual sync took priority)
            if (dashLocalLibrary[it.vendor][it.collection].some(x => x.code === it.code)) return;
            const entry = {
                code: it.code,
                width: parseFloat(it.width) || 1.25,
                file: it.path, // string path — _libEntryToUrl/_libEntryToDataUrl handle the URL case
            };
            // Floater swatches carry a faceWidth (canvas face visible from front);
            // floaterInset = faceWidth + FLOATER_SHADOW_REVEAL is computed at swatch-pick time.
            if (it.faceWidth !== undefined && it.faceWidth !== null && !isNaN(parseFloat(it.faceWidth))) {
                entry.faceWidth = parseFloat(it.faceWidth);
            }
            // Optional profile depth (Fr.H) and rabbet depth — captured from
            // filename tags _d<depth> and _r<rabbet>. Both auto-populate the
            // dashboard form fields when this swatch is picked.
            if (it.depth !== undefined && it.depth !== null && !isNaN(parseFloat(it.depth))) {
                entry.depth = parseFloat(it.depth);
            }
            if (it.rabbet !== undefined && it.rabbet !== null && !isNaN(parseFloat(it.rabbet))) {
                entry.rabbet = parseFloat(it.rabbet);
            }
            dashLocalLibrary[it.vendor][it.collection].push(entry);
        });
        populateDashVendorDropdown();
    } catch (e) {
        // network error, parse error, etc. — non-fatal, app still works.
        console.warn('Bundled library manifest could not be loaded:', e);
    }
}

// ──────────────────────────────────────────────────────────────────────────
// CUSTOM LIBRARY PERSISTENCE (localStorage)
// ──────────────────────────────────────────────────────────────────────────
// User-uploaded swatches (from the Sync Folder workflow) get auto-resized
// to a max dimension and saved to localStorage so they persist across
// browser sessions. The bundled GitHub library is unaffected — bundled
// entries store URL paths (strings), not data URLs, so they're naturally
// excluded from persistence (we serialise only data-URL entries).
//
// Size tradeoff: localStorage is ~5MB per domain. Resizing swatches to
// 600px max keeps each one to ~50-100KB after base64 encoding, so users
// can store ~50 swatches before hitting the limit.
//
// Override semantics: a saved entry with the same vendor/collection/code
// as a bundled entry wins (matches the existing manual-sync behaviour).

const CUSTOM_LIBRARY_STORAGE_KEY = 'dashCustomLibrary';
const CUSTOM_LIBRARY_MAX_DIMENSION = 600; // px on the longest side
const CUSTOM_LIBRARY_QUOTA_BYTES = 5 * 1024 * 1024; // 5MB conservative estimate

// Resize a data URL to fit within maxSize on its longest dimension. Returns
// the resized data URL via callback. Preserves aspect ratio. PNG output so
// transparency is kept (frame swatches sometimes use transparent corners).
// If the source is already smaller than maxSize, pass through unchanged.
function resizeImageDataUrl(srcDataUrl, maxSize, callback) {
    const img = new Image();
    img.onload = () => {
        const w = img.naturalWidth;
        const h = img.naturalHeight;
        if (w <= maxSize && h <= maxSize) {
            // Already small enough — no resize needed
            callback(srcDataUrl);
            return;
        }
        const scale = maxSize / Math.max(w, h);
        const newW = Math.round(w * scale);
        const newH = Math.round(h * scale);
        const c = document.createElement('canvas');
        c.width = newW; c.height = newH;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, 0, 0, newW, newH);
        // PNG (lossless) preserves transparency in frame swatches. The size
        // saving comes from the dimension reduction, not lossy compression.
        callback(c.toDataURL('image/png'));
    };
    img.onerror = () => callback(srcDataUrl); // fall back to original on error
    img.src = srcDataUrl;
}

// ── THE BOUND ON AN IMPORTED PAGE BACKGROUND ────────────────────────────
// A PAGE BACKGROUND WAS THE ONE IMAGE IMPORT WITH NO BOUND AT ALL, and it is
// the one that fills a whole page, so it attracts the largest file anybody
// has. Measured on a real project: two backgrounds at 5.51 MB and 5.58 MB
// were 11.1 MB of a 22.9 MB file, nearly half of it, against 3.9 MB of
// artwork across fourteen pieces. Every sibling path already bounds (1000 px
// for dashboard artwork, 1100 from the shape popup, 1400 on a drop); this one
// wrote FileReader's result straight into the project.
//
// THE COST IS THE ENCODING, NOT THE PIXELS, and that is the whole design.
// Both of those were 1728x1956 RGBA PNGs: 3.4 megapixels, comfortably under
// what the page can use, so a dimension bound would have left them untouched
// and resizeImageDataUrl above would have returned them verbatim. A
// photograph stored as RGBA PNG runs about twenty times its JPEG size. So
// this re-encodes, and the dimension ceiling below is a backstop against a
// camera export rather than the lever.
//
// PNG IS KEPT WHEN THE IMAGE ACTUALLY USES TRANSPARENCY. A background is
// composited over the theme's own colour, so alpha can genuinely matter - but
// a photo saved out as RGBA carries a fully opaque alpha channel and loses
// nothing by dropping it. resizeImageDataUrl stays exactly as it is: it
// serves frame swatches, which are line work on transparency where lossy
// encoding would be the wrong trade.
//
// DELIBERATELY NOT APPLIED TO THE FLOORPLAN OR A CUSTOM SWATCH, which are the
// other two unbounded paths. Both are usually LINE WORK, where JPEG ringing
// eats hairlines and a plan is the drawing an installer works from. Those
// want palette reduction rather than this, which is a different piece of work.
const PAGE_BG_MAX_ZOOM = 3;   // the top of the Zoom slider in the page theme panel

// A FUNCTION, not a const: PAGE_FORMAT and _PDF_QUALITY are declared further
// down and a const here would read them in the TDZ, which is the trap
// TITLE_SIZE_DEFAULT, _elevIdSeq and IG_LEG_TOP_GAP were each caught by.
// Derived rather than chosen: the page is PAGE_FORMAT[0] points wide, the
// highest export renders it at _PDF_QUALITY.print.r times that, and Zoom crops
// into it by up to PAGE_BG_MAX_ZOOM. Past that product a background is
// carrying pixels no export can ever print.
function _pageBgMaxEdge() {
    try { return Math.round(PAGE_FORMAT[0] * _PDF_QUALITY.print.r * PAGE_BG_MAX_ZOOM); }
    catch (e) { return 8424; }
}

// Does any pixel actually carry transparency? Scanned in full rather than
// sampled: a stride would miss a small cut-out corner and flatten it to black,
// and this runs once on an import rather than in a draw loop.
function _imageDataHasAlpha(ctx, w, h) {
    try {
        const d = ctx.getImageData(0, 0, w, h).data;
        for (let i = 3; i < d.length; i += 4) if (d[i] !== 255) return true;
        return false;
    } catch (e) {
        // No 2d context, or a tainted canvas. Assume alpha and keep PNG:
        // guessing the other way flattens transparency the page was relying on.
        return true;
    }
}

// Calls back with (dataUrl, width, height). Never throws and never rejects:
// it sits on an import path, and the fallback everywhere is the image exactly
// as it arrived.
function _boundImageDataUrl(srcDataUrl, maxEdge, quality, callback) {
    const done = (url, w, h) => { try { callback(url, w, h); } catch (e) {} };
    if (!srcDataUrl) { done(srcDataUrl, 0, 0); return; }
    const img = new Image();
    img.onload = () => {
        const w0 = img.naturalWidth || 0, h0 = img.naturalHeight || 0;
        if (!w0 || !h0) { done(srcDataUrl, w0, h0); return; }
        const sc = Math.min(1, maxEdge / Math.max(w0, h0));
        const w = Math.max(1, Math.round(w0 * sc)), h = Math.max(1, Math.round(h0 * sc));
        let out = null;
        try {
            const c = document.createElement('canvas');
            c.width = w; c.height = h;
            const ctx = c.getContext('2d');
            ctx.drawImage(img, 0, 0, w, h);
            out = _imageDataHasAlpha(ctx, w, h)
                ? c.toDataURL('image/png')
                : c.toDataURL('image/jpeg', quality);
        } catch (e) { out = null; }
        // NEVER HAND BACK SOMETHING BIGGER THAN WHAT ARRIVED. A small JPEG
        // re-encoded as PNG grows, and so does anything already under the
        // bound whose format was already the right one. The original is then
        // the right answer, and its own dimensions go back with it.
        if (!out || out.length >= srcDataUrl.length) { done(srcDataUrl, w0, h0); return; }
        done(out, w, h);
    };
    img.onerror = () => done(srcDataUrl, 0, 0);
    img.src = srcDataUrl;
}

// Serialise every user-uploaded swatch to localStorage. We walk the
// dashLocalLibrary structure and only persist entries whose `file` is a
// data URL string (which is the format manually uploaded swatches use after
// being read by FileReader.readAsDataURL). Bundled entries have URL paths
// like "library/vendor/collection/file.png" and are NOT data URLs, so they
// pass through this filter naturally.
function saveCustomLibraryToStorage() {
    try {
        const customEntries = [];
        Object.keys(dashLocalLibrary).forEach(vendor => {
            Object.keys(dashLocalLibrary[vendor]).forEach(collection => {
                dashLocalLibrary[vendor][collection].forEach(entry => {
                    // file may be a File object, a URL string (bundled), or a
                    // data URL string (manually uploaded + resized). We only
                    // persist data URLs.
                    if (typeof entry.file === 'string' && entry.file.startsWith('data:')) {
                        const persisted = {
                            vendor, collection,
                            code: entry.code,
                            width: entry.width,
                            file: entry.file,
                        };
                        if (entry.faceWidth !== undefined) persisted.faceWidth = entry.faceWidth;
                        if (entry.depth !== undefined) persisted.depth = entry.depth;
                        if (entry.rabbet !== undefined) persisted.rabbet = entry.rabbet;
                        customEntries.push(persisted);
                    }
                });
            });
        });
        const serialized = JSON.stringify(customEntries);
        localStorage.setItem(CUSTOM_LIBRARY_STORAGE_KEY, serialized);
        return { ok: true, count: customEntries.length, bytes: serialized.length };
    } catch (err) {
        // Most likely cause: QuotaExceededError. Don't blow up — return the
        // failure so the caller can surface a friendly message.
        return { ok: false, error: err.message || String(err) };
    }
}

// Restore previously-saved swatches into dashLocalLibrary. Called once on
// startup AFTER loadBundledLibrary completes. A saved entry overrides a
// bundled entry with the same vendor/collection/code (same precedence rule
// as the live syncDashLibraryFolder workflow). After hydration, refreshes
// the vendor dropdown so the user immediately sees their library.
function restoreCustomLibraryFromStorage() {
    try {
        const raw = localStorage.getItem(CUSTOM_LIBRARY_STORAGE_KEY);
        if (!raw) return;
        const entries = JSON.parse(raw);
        if (!Array.isArray(entries) || entries.length === 0) return;
        entries.forEach(e => {
            if (!e.vendor || !e.collection || !e.code || !e.file) return;
            if (!dashLocalLibrary[e.vendor]) dashLocalLibrary[e.vendor] = {};
            if (!dashLocalLibrary[e.vendor][e.collection]) dashLocalLibrary[e.vendor][e.collection] = [];
            const arr = dashLocalLibrary[e.vendor][e.collection];
            const existing = arr.find(x => x.code === e.code);
            const entry = {
                code: e.code,
                width: e.width,
                file: e.file, // data URL
            };
            if (e.faceWidth !== undefined) entry.faceWidth = e.faceWidth;
            if (e.depth !== undefined) entry.depth = e.depth;
            if (e.rabbet !== undefined) entry.rabbet = e.rabbet;
            if (existing) {
                // Saved entry overrides bundled (matches sync-folder behaviour)
                Object.assign(existing, entry);
            } else {
                arr.push(entry);
            }
        });
        populateDashVendorDropdown();
    } catch (err) {
        // Corrupted JSON or unexpected error — non-fatal. User still gets the
        // bundled library, just loses their previous personal swatches.
        console.warn('Could not restore custom library from storage:', err);
    }
}

// Return stats about persisted library size for the UI indicator.
function getCustomLibraryStorageStats() {
    try {
        const raw = localStorage.getItem(CUSTOM_LIBRARY_STORAGE_KEY) || '';
        const bytes = raw.length; // approximate; UTF-16 internally but base64 is ASCII
        const entries = raw ? JSON.parse(raw) : [];
        const count = Array.isArray(entries) ? entries.length : 0;
        const pct = Math.round((bytes / CUSTOM_LIBRARY_QUOTA_BYTES) * 100);
        return { count, bytes, percentOfLimit: pct };
    } catch (e) {
        return { count: 0, bytes: 0, percentOfLimit: 0 };
    }
}

// Wipe all persisted custom swatches and remove them from the in-memory
// library. Used by the "Clear my swatches" UI affordance.
function clearCustomLibrary() {
    try {
        localStorage.removeItem(CUSTOM_LIBRARY_STORAGE_KEY);
    } catch (e) { /* ignore */ }
    // Remove all data-URL-backed entries from dashLocalLibrary in memory.
    Object.keys(dashLocalLibrary).forEach(vendor => {
        Object.keys(dashLocalLibrary[vendor]).forEach(collection => {
            dashLocalLibrary[vendor][collection] = dashLocalLibrary[vendor][collection].filter(
                e => !(typeof e.file === 'string' && e.file.startsWith('data:'))
            );
            // Clean up empty collections
            if (dashLocalLibrary[vendor][collection].length === 0) {
                delete dashLocalLibrary[vendor][collection];
            }
        });
        // Clean up empty vendors
        if (Object.keys(dashLocalLibrary[vendor]).length === 0) {
            delete dashLocalLibrary[vendor];
        }
    });
    populateDashVendorDropdown();
}

// Visibility flags for the two Layout Guides toggle buttons that don't map
// to a simple layer (group box + edge gaps). letters/spacing/wall already
// have their own Layout Guides layer toggles, so they're not duplicated here.
// Persisted to localStorage. Default: visible.
let dimVisibility = {
    groupBox: true,   // group dimension callouts
    edgeGap: true,    // edge-gap (distance-to-wall) dimensions
    wallDims: true,   // overall wall width/height dimensions (default ON)
    customLines: true, // custom measure-tool lines
    imageCode: false,  // artwork image-code caption beneath each frame (opt-in)
    // Height dimension on the scale figure (floor to crown). Opt-in like imageCode,
    // so no existing deck gains a dimension it never had. Deck-wide, like every
    // other entry here — saveDimVisibility drops the cached elevation captures.
    figureHeight: false,
    // Print EQ on spacing and edge-gap dimensions instead of the measurement — the
    // drafting convention for "these are equally spaced", used heavily in the Ford
    // catalog (ART-2/3/4/5/8 and ART-9 SHORT). An EXPLICIT toggle, not an automatic
    // "are these equal?" test: EQ is a statement of intent by the designer, and a
    // dimension that silently changed from a number to EQ when two gaps happened to
    // match would be worse than either. Opt-in, so no existing deck's dimensions
    // change meaning on upgrade.
    spacingEQ: false,
};
// The label a spacing / edge-gap dimension carries. ONE helper for all six call
// sites, so EQ mode can't reach some of them and not others — an elevation with
// three gaps reading EQ, EQ and 26" is worse than any consistent choice.
function _spacingLabel(v) {
    return dimVisibility.spacingEQ ? 'EQ' : elevFmtU(v);
}

// Styling for the image-code caption beneath each frame. Persisted separately
// so codes can be made subtle without affecting dimensions. Studio default is
// Messina 9pt in #9c9c9c — the same values as Deck Studio's
// "Captions / image code" style, so an elevation and a deck page match.
//
// `fontToken` is the FRAME_FONT_LIBRARY token the user picked; `font` is the
// resolved CSS stack, kept in sync by _normalizeImageCodeStyle(). Every
// renderer already reads `font`, so it stays the derived field.
let imageCodeStyle = {
    color: '#9c9c9c',
    size: 9,
    fontToken: 'serif',
    font: null,
    weight: 400,
};
// The pre-library defaults. A stored style still sitting on all three of them
// was never actually customised, so it adopts the new studio defaults instead
// of pinning an old build's look forever.
const _IMG_CODE_LEGACY_DEFAULTS = { color: '#222222', size: 10, font: 'Arial, Helvetica, sans-serif' };
function _normalizeImageCodeStyle() {
    if (!imageCodeStyle.fontToken) imageCodeStyle.fontToken = _fontToken(imageCodeStyle.font, 'serif');
    imageCodeStyle.font = _fontCss(imageCodeStyle.fontToken, 'serif');
}
function saveImageCodeStyle() {
    try { localStorage.setItem('frameImageCodeStyle', JSON.stringify(imageCodeStyle)); } catch (e) {}
}
function loadImageCodeStyle() {
    try {
        const v = JSON.parse(localStorage.getItem('frameImageCodeStyle'));
        if (v && typeof v === 'object') {
            const untouched = !v.fontToken && v.color === _IMG_CODE_LEGACY_DEFAULTS.color &&
                v.size === _IMG_CODE_LEGACY_DEFAULTS.size && v.font === _IMG_CODE_LEGACY_DEFAULTS.font;
            if (!untouched) imageCodeStyle = Object.assign(imageCodeStyle, v);
        }
    } catch (e) {}
    _normalizeImageCodeStyle();
}
loadImageCodeStyle();

function _syncImageCodeStyleControls() {
    _normalizeImageCodeStyle();
    const c = document.getElementById('imgCodeColor'); if (c) c.value = imageCodeStyle.color;
    const ch = document.getElementById('imgCodeColorHex'); if (ch) ch.textContent = imageCodeStyle.color;
    const s = document.getElementById('imgCodeFontSize'); if (s) s.value = imageCodeStyle.size;
    const sv = document.getElementById('imgCodeFontSizeVal'); if (sv) sv.textContent = imageCodeStyle.size + 'px';
    const f = document.getElementById('imgCodeFontFamily'); if (f) _fillFontSelect(f, imageCodeStyle.fontToken, 'serif');
    _frameSwatchesInto(document.getElementById('imgCodeColorSwatches'), imageCodeStyle.color, (hex) => {
        const ci = document.getElementById('imgCodeColor'); if (ci) ci.value = hex;
        imageCodeStyle.color = hex;
        applyImageCodeStyleFromModal();
    });
    [['imgCodeWeightReg',400],['imgCodeWeightSemi',600],['imgCodeWeightBold',700]].forEach(([id,w]) => {
        const btn = document.getElementById(id); if (btn) btn.classList.toggle('active', imageCodeStyle.weight === w);
    });
}
function applyImageCodeStyleFromModal() {
    const c = document.getElementById('imgCodeColor');
    const s = document.getElementById('imgCodeFontSize');
    const f = document.getElementById('imgCodeFontFamily');
    if (c) { imageCodeStyle.color = c.value; const ch = document.getElementById('imgCodeColorHex'); if (ch) ch.textContent = c.value; }
    if (s) { imageCodeStyle.size = parseInt(s.value, 10) || 9; const sv = document.getElementById('imgCodeFontSizeVal'); if (sv) sv.textContent = imageCodeStyle.size + 'px'; }
    if (f && f.value) imageCodeStyle.fontToken = f.value;
    _normalizeImageCodeStyle();
    _frameSwatchesInto(document.getElementById('imgCodeColorSwatches'), imageCodeStyle.color, (hex) => {
        const ci = document.getElementById('imgCodeColor'); if (ci) ci.value = hex;
        imageCodeStyle.color = hex;
        applyImageCodeStyleFromModal();
    });
    saveImageCodeStyle();
    drawElevAll();
}
function setImageCodeWeight(w) {
    imageCodeStyle.weight = w;
    _syncImageCodeStyleControls();
    saveImageCodeStyle();
    drawElevAll();
}

function loadDimVisibility() {
    try {
        const raw = localStorage.getItem('dimVisibility');
        if (raw) {
            const v = JSON.parse(raw);
            if (v && typeof v === 'object') dimVisibility = Object.assign(dimVisibility, v);
        }
    } catch (e) { /* defaults */ }
}

// Layout guides and dimension styling are DECK-WIDE: turning one off applies to
// every elevation at once. So one change makes every cached elevation snapshot
// and every built page preview stale simultaneously, and you should never have
// to visit each elevation and refresh its preview for the change to reach the
// PDF.
//
// It used to be inconsistent about that, which is the confusing part: the
// install/breaker capture cache is keyed partly on a "guide stamp" built from
// each layer's style.display, so toggles that flip a layer (Labels, Spacing,
// Person, Guides, Grid, Centers) changed the key and did get re-captured — while
// the dimVisibility ones (group box, edge gap, image code) change no layer's
// display at all, so the key was identical and a stale snapshot was silently
// reused. None of the toggles call pushHistory either, so _dsEditGen — the other
// half of the key — never moved to save them.
//
// Rather than keep extending the stamp (it has already been missed twice: once
// for person-wrap, once for annotationStyle), invalidate outright.
function _elevGuidesChanged() {
    try { for (const k in _igCapCache) delete _igCapCache[k]; } catch (e) {}
    try { if (typeof _dsClearBuiltAll === 'function') _dsClearBuiltAll(); } catch (e) {}
}
function saveDimVisibility() {
    try { localStorage.setItem('dimVisibility', JSON.stringify(dimVisibility)); }
    catch (e) { /* ignore */ }
    // Every dimVisibility toggle routes through here, so this one call covers
    // wall dims, group box, edge gap, image code and custom lines.
    _elevGuidesChanged();
}

// Does the current elevation have at least one group dimension?
function anyGroupDimExists() {
    const ce = elevations[currentElevIndex];
    return !!(ce && Array.isArray(ce.groupDims) && ce.groupDims.length > 0);
}

// Does any frame in the current elevation have an edge-gap toggle enabled?
function anyEdgeGapActive() {
    return elevFrames.some(f => {
        const dt = f.distToggles;
        return dt && (dt.ceiling || dt.floor || dt.left || dt.right);
    });
}

// A guide that has nothing on this wall to show is faded (18.54). Faded alone read as
// "broken" or "off", so the tooltip now says WHY and how to make one, and the tile is
// marked aria-disabled. The base tooltip is kept on the element so it is never stacked.
function _lgAvail(btn, exists, how) {
    if (!btn) return;
    if (btn.dataset.baseTitle == null) btn.dataset.baseTitle = btn.title || '';
    btn.style.opacity = exists ? '1' : '0.4';
    if (exists) { btn.removeAttribute('aria-disabled'); btn.title = btn.dataset.baseTitle; }
    else { btn.setAttribute('aria-disabled', 'true'); btn.title = btn.dataset.baseTitle + '\n\nNothing on this wall yet: ' + how; }
}
// Sync the two Layout Guides toggle buttons' blue (active) state:
//   - Group Box button: blue when a group dim exists AND it's visible
//   - Edge Gap button: blue when any edge gap is active AND visible
// Called after drawElevAll and after creating/removing group dims or edge gaps.
function syncLayoutGuideButtonStates() {
    const gbBtn = document.getElementById('groupBoxToggle');
    if (gbBtn) {
        const exists = anyGroupDimExists();
        gbBtn.classList.toggle('active', exists && dimVisibility.groupBox);
        _lgAvail(gbBtn, exists, 'select two or more frames and press the group dimension button in Add & Arrange (Art tab).');
    }
    const egBtn = document.getElementById('edgeGapToggle');
    if (egBtn) {
        const exists = anyEdgeGapActive();
        egBtn.classList.toggle('active', exists && dimVisibility.edgeGap);
        _lgAvail(egBtn, exists, 'click a frame\'s Edge button in the frame list (Art tab).');
    }
    // Wall dims: always available (not conditional on existence). Keep the
    // arch-dim-layer display + button blue state in sync with the flag.
    const wdBtn = document.getElementById('wallDimToggle');
    const archLayer = document.getElementById('arch-dim-layer');
    if (archLayer) archLayer.style.display = dimVisibility.wallDims ? 'block' : 'none';
    if (wdBtn) wdBtn.classList.toggle('active', dimVisibility.wallDims);
    // Wireframe (18.49): project data, so it can change under the button (a deck preset, undo, a load).
    const wireBtn = document.getElementById('wireframeToggle');
    if (wireBtn) wireBtn.classList.toggle('active', _isWireframe());
    // Unit suffix toggle: active when interior suffix is shown.
    // Custom lines toggle: blue when lines exist + visible; dim when none.
    const clBtn = document.getElementById('customLinesToggle');
    if (clBtn) {
        const exists = (typeof getElevCustomLines === 'function') && getElevCustomLines().length > 0;
        clBtn.classList.toggle('active', exists && dimVisibility.customLines);
        _lgAvail(clBtn, exists, 'press M on the wall to draw a measurement line.');
    }
    // Image-code caption toggle: active when the flag is on.
    const icBtn = document.getElementById('imageCodeToggle');
    if (icBtn) icBtn.classList.toggle('active', dimVisibility.imageCode);
    // EQ mode on spacing / edge-gap dims.
    const eqBtn = document.getElementById('spacingEQToggle');
    if (eqBtn) eqBtn.classList.toggle('active', dimVisibility.spacingEQ);
    // EGD wall: PER-ELEVATION, not a global preference, so it reads the current wall
    // rather than a dimVisibility flag. Every other button in this row is deck-wide,
    // which is exactly why it would be easy to add it to the wrong list.
    // TWO BUTTONS, and exactly one of them is lit. A single toggle could only show the
    // state it was in and left the other mode unnamed, so a designer had to already know
    // EGD mode existed to go looking for it. Side by side, the wall's mode is the
    // highlighted one and the alternative is right there with a name on it.
    const on = _isEgdWall(elevations[currentElevIndex]);
    const egdBtn = document.getElementById('egdWallBtn');
    const artBtn = document.getElementById('artWallBtn');
    // WF is DERIVED from the glass, not a stored third mode: a wall with a glazing run on
    // it IS a window-film wall, and a separate flag would be one more thing to keep in
    // step with the runs. It is therefore not exclusive with the other two — a glazed wall
    // is normally an ART wall, which is the thing the hint below explains.
    const el0 = elevations[currentElevIndex];
    const hasGlass = !!(el0 && Array.isArray(el0.glazing) && el0.glazing.length);
    const wfBtn = document.getElementById('wfWallBtn');
    // ART is lit only when the wall is NEITHER of the others, so the row reads as "a plain
    // wall, plus whatever is switched on", and a lit EGD or WF is visibly something that
    // can be switched back off (its tooltip says how).
    const artOn = !on && !hasGlass;
    if (wfBtn) { wfBtn.classList.toggle('active', hasGlass); wfBtn.title = hasGlass ? 'WF wall is ON. Click to turn it off (removes the window panels from this wall).' : 'WF wall: window film on glass. Adds the standard run of three panels and opens the Glass tab.'; }
    if (egdBtn) { egdBtn.classList.toggle('active', on); egdBtn.title = on ? 'EGD wall is ON. Click to turn it off and go back to an art wall.' : 'EGD wall: a wallcovering fills this wall and stays inside it, above the baseboard.'; }
    if (artBtn) { artBtn.classList.toggle('active', artOn); artBtn.title = artOn ? 'Art wall, the default: framed art hangs on this wall.' : 'Back to a plain art wall: turns EGD and WF off.'; }
    // WHAT THE MODE GOVERNS, said out loud, and keyed to what is actually on this wall.
    // The pair of buttons implies you must pick EGD for any EGD or WF work; that is wrong
    // and costly, because window film is sized to the GLASS and the mode does not touch
    // it. A glazed wall left on ART is correct, and this is the only place that says so.
    _syncCatalogueBtn();
    const hint = document.getElementById('wallModeHint');
    if (hint) {
        hint.textContent = on
            ? 'Wallcovering dropped here fills the wall and stays inside it. Window film and framed art are unaffected.'
            : (hasGlass
                ? 'Window film sits on the glass, so this wall does not need EGD mode. Switch only if a wallcovering should fill it.'
                : 'Framed art hangs on the wall. Switch to EGD only if a wallcovering should fill this wall.');
    }
}


// The catalogue mockup switch. Lit from the wall itself, like the wall-mode pair above
// it and unlike every deck-wide control in this panel. The hint is the only place that
// says what the mode actually does, and an option wall says what it is rather than
// offering a switch it will refuse.
function _syncCatalogueBtn() {
    const btn = document.getElementById('catMasterBtn');
    const hint = document.getElementById('catMasterHint');
    const elev = (typeof elevations !== 'undefined' && elevations) ? elevations[currentElevIndex] : null;
    const isMaster = _isCatalogueMaster(elev);
    const isOpt = _isCatalogueOption(elev);
    if (btn) {
        btn.classList.toggle('active', isMaster);
        btn.disabled = isOpt;
        btn.style.opacity = isOpt ? '0.5' : '';
    }
    // The duplicate control is the way an option is added, so it has to say so. Two
    // gestures behind one button is fine; two gestures behind one unchanged tooltip is
    // how a designer learns the wrong one.
    // THE TWO AXES GET TWO CONTROLS. Duplicate means "same layout, different images";
    // Add arrangement means "same spot, different layout". One button doing both behind a
    // modifier is how a designer learns whichever one they pressed first.
    // The ROW hides, not the buttons: they are alone on it now, so hiding only them
    // would leave an empty 26px band on every wall outside a catalogue.
    const addRow = document.getElementById('catAddRow');
    if (addRow) addRow.style.display = (isMaster || isOpt) ? 'flex' : 'none';
    const set = document.getElementById('catSetBtn');
    if (set) {
        const c2 = _catBaseCode(isOpt ? _catMasterOf(elev) : elev);
        const p2 = _catPlacementKey(c2);
        const n2 = c2 ? _catSetsOf(p2).length : 0;
        set.title = c2
            ? ('Add a DIFFERENT SET OF FRAMES at ' + p2 + ' \u2014 a single piece where this is a salon hang. '
               + 'Its frames are its own and nothing here reaches the other sets; it shares this placement\u2019s pin on the floorplan. '
               + n2 + ' frame set' + (n2 === 1 ? '' : 's') + ' so far.')
            : 'Place a piece carrying an item code before adding a frame set.';
    }
    const arr = document.getElementById('catArrBtn');
    if (arr) {
        const code = _catBaseCode(isOpt ? _catMasterOf(elev) : elev);
        const place = _catPlacementKey(code);
        const n = code ? _catArrangementsOf(place).length : 0;
        arr.title = code
            ? ('Add another LAYOUT for ' + place + ' \u2014 a diptych where this is a salon hang, say. It becomes its own mockup with its own breaker page and shares this placement\u2019s pin on the floorplan, so the plan still shows one location. '
               + n + ' arrangement' + (n === 1 ? '' : 's') + ' so far.'
               + (isOpt ? ' Taken from an option, the new arrangement starts empty with its first option carrying these images.' : ''))
            : 'Place a piece carrying an item code before adding a second arrangement.';
    }
    // The label + own-frames row, on a layout that is not the primary. The primary has
    // nothing to follow, so offering it "Own frames" would be a control with no meaning.
    const lrow = document.getElementById('catLayoutRow');
    if (lrow) {
        lrow.style.display = isMaster ? 'flex' : 'none';
        const li = document.getElementById('catLayoutLabel');
        if (li && document.activeElement !== li) li.value = _catLayoutLabel(elev);
    }
    const dup = document.getElementById('dupElevBtn');
    if (dup) dup.title = isMaster
        ? ('Add art option ' + _catNextOptionNum(elev) + ' \u2014 a copy of this arrangement with its own images and item codes')
        : 'Duplicate this wall';
    if (!hint) return;
    if (isOpt) {
        const m = _catMasterOf(elev);
        hint.textContent = 'Art option ' + (elev.catalogueOption || '') + ' of ' + ((m && m.name) || 'its mockup')
            + '. Size, position and frame spec follow the mockup; only the artwork is this wall\'s own.';
    } else if (isMaster) {
        const opts = _catOptionsOf(elev);
        const code = _catBaseCode(elev);
        const place = _catSetKey(code);
        const prim = _catPrimaryArr(place);
        const isPrim = !prim || prim === elev;
        const sibs = _catArrangementsOf(place).length;
        // ONE SENTENCE FOR WHAT IT GOVERNS, ONE FOR WHAT IT FOLLOWS. Those are the two
        // questions a designer has before editing a frame, and the panel used to answer
        // neither: every layout described itself as "the arrangement".
        hint.textContent = (isPrim
            ? ('Frame set ' + _catSetNum(code) + ' at ' + _catPlacementKey(code)
               + '. These frames are its own; sizes, mouldings and mats set here reach '
               + (sibs > 1 ? ('the other ' + (sibs - 1) + ' layout' + (sibs === 2 ? '' : 's') + ' of this set') : 'any layout you add to this set')
               + ' and no other set.')
            : ('Layout ' + (_catArrLetter(code) || '') + ' of frame set ' + place
               + '. Frame specs follow ' + ((prim && _catBaseCode(prim)) || 'the primary') + '; the positions are this wall\u2019s.'))
            + ' Drawn with no artwork \u2014 duplicate it to add image set ' + _catNextOptionNum(elev) + '. '
            + (opts.length ? (opts.length + ' image set' + (opts.length === 1 ? '' : 's') + ' follow this wall.') : 'No image sets yet.');
    } else {
        // A plain wall says nothing here: options are made from Deck Studio now, and a
        // line pointing at a button that no longer exists is worse than no line.
        hint.textContent = '';
    }
}
// Toggle group-box visibility (only meaningful if one exists).
function toggleGroupBoxVisibility(btn) {
    if (!anyGroupDimExists()) return; // nothing to toggle
    dimVisibility.groupBox = !dimVisibility.groupBox;
    saveDimVisibility();
    drawElevAll();
}

// Toggle edge-gap dimension visibility (only meaningful if one exists).
function toggleEdgeGapVisibility(btn) {
    if (!anyEdgeGapActive()) return;
    dimVisibility.edgeGap = !dimVisibility.edgeGap;
    saveDimVisibility();
    drawElevAll();
}

// Toggle wall dimension visibility (arch-dim-layer). Default ON.
function toggleWallDims(btn) {
    dimVisibility.wallDims = !dimVisibility.wallDims;
    saveDimVisibility();
    const layer = document.getElementById('arch-dim-layer');
    if (layer) layer.style.display = dimVisibility.wallDims ? 'block' : 'none';
    if (btn) btn.classList.toggle('active', dimVisibility.wallDims);
    drawElevAll();
}

// Toggle custom measure-tool line visibility (Layout Guides ruler button).
function toggleCustomLinesVisibility(btn) {
    const anyLines = getElevCustomLines().length > 0;
    if (!anyLines) return;
    dimVisibility.customLines = !dimVisibility.customLines;
    saveDimVisibility();
    if (btn) btn.classList.toggle('active', dimVisibility.customLines);
    drawElevAll();
}

function toggleArtworkVisibility(btn) {
    _showArtwork = !_showArtwork;
    if (btn) btn.classList.toggle('active', _showArtwork);
    drawElevAll();
}

// EQ instead of the measurement on spacing and edge-gap dims. Deck-wide like every
// other entry in dimVisibility, and saveDimVisibility drops the cached elevation
// captures so install-guide and breaker pages pick it up too.
function toggleSpacingEQ(btn) {
    dimVisibility.spacingEQ = !dimVisibility.spacingEQ;
    saveDimVisibility();
    if (btn) btn.classList.toggle('active', dimVisibility.spacingEQ);
    drawElevAll();
}
function toggleImageCodeVisibility(btn) {
    dimVisibility.imageCode = !dimVisibility.imageCode;
    saveDimVisibility();
    if (btn) btn.classList.toggle('active', dimVisibility.imageCode);
    drawElevAll();
}

// Height dimension on the scale figure. A tick box in Settings → Scale Figure
// rather than a Layout Guides button: it belongs beside the shade control it
// shares a subject with, and gear popups are where settings live.
function toggleFigureDim(on) {
    dimVisibility.figureHeight = !!on;
    saveDimVisibility();
    _syncFigureDimToggle();
    drawElevAll();
}
function _syncFigureDimToggle() {
    const cb = document.getElementById('figureDimToggle');
    if (cb) cb.checked = !!dimVisibility.figureHeight;
    // It is only ever drawn on a visible figure, so say so rather than leaving a
    // ticked box with nothing on the wall to show for it.
    const note = document.getElementById('figureDimHint');
    if (note) {
        const wrap = document.getElementById('person-wrap');
        const shown = wrap && wrap.style.display !== 'none' && wrap.style.display !== '';
        note.style.display = (dimVisibility.figureHeight && !shown) ? 'block' : 'none';
    }
}

function toggleTheme() { document.body.classList.toggle('light-theme'); }

// ── Export helpers: light theme + settling ────────────────────────────────
// Exports render in light theme for print consistency. Each individual
// elevation export used to add/remove the class itself, so a deck with N
// elevations flipped the whole UI dark→light→dark N times — a visible strobe
