            let h = parseFloat((108 * uf).toFixed(2));
            let px = parseFloat((-60 * uf).toFixed(2));
            elevations.push({ id: _elevNewId(), name: "Elevation 1", frames: [], wallW: w, wallH: h, personPos: {x: px} });
