        const key = norm(info.code);
        const rec = byCode[key] || (byCode[key] = { code: info.code, vendor: vendor, collection: collection, corner: '', profile: '', face: '', depth: '', rabbet: '' });
        const full = node.path;
        const isProfile = inProfiles || (!inCorners && !info.dims);
