            if (f.profileImg && (f.profileImg.naturalWidth || f.profileImg.width)) {
                const iw = f.profileImg.naturalWidth || f.profileImg.width, ih = f.profileImg.naturalHeight || f.profileImg.height;
                const fit = Math.min(pfMax / iw, pfMax / ih);
                const dw = iw * fit, dh = ih * fit;
                try { _addPngImage(doc, f.profileImg, pfX + (pfMax - dw) / 2, y + (rowH - dh) / 2, dw, dh); } catch (e) { try { doc.addImage(f.profileImg, 'JPEG', pfX + (pfMax - dw) / 2, y + (rowH - dh) / 2, dw, dh); } catch (e2) {} }
            }
            // Text block
            const tx0 = pfX + pfMax + 14 * S;
            const tW = cx + colW - tx0;
