                const cropped = _cropToCanvas(im, w, h, aspImg, t.zoom || 1, t.panX || 0, t.panY || 0, t.fit || 'cover');
                if (t.fit === 'contain') { _addPngImage(doc, cropped.toDataURL('image/png'), x, y, w, h); }
