    // The open category follows whatever is armed, so it doesn't snap back to the first
    // group every time the panel rebuilds.
    const openCat = _ctxPaletteCat || _ctxCatOf(_ctxArmedPreset);
    const group = CONTEXT_LIBRARY.find(c => c.cat === openCat) || CONTEXT_LIBRARY[0];
    let html = `<div class="ctx-cats">`;
    CONTEXT_LIBRARY.forEach(c => {
        html += `<button class="ctx-cat${c.cat === group.cat ? ' ctx-cat-on' : ''}"
                    onclick="setContextPaletteCat('${c.cat}')">${c.cat}</button>`;
    });
    html += `</div>`;
    // Two gestures on one chip, which is why these sit above the list rather than
    // beside an "add" at the bottom:
