        const f2 = elevFrames.find(fr => fr.letter === l2);
        if (f1 && Array.isArray(f1.dimTo)) f1.dimTo = f1.dimTo.filter(x => x !== l2);
        if (f2 && Array.isArray(f2.dimTo)) f2.dimTo = f2.dimTo.filter(x => x !== l1);
