    if (dl && dl.style.display !== 'block') { dl.style.display = 'block'; const tb = document.getElementById('dimToggle'); if (tb) tb.classList.add('active'); }
    // Redraw the wall you're looking at. This used to call renderElevation(),
    // which does not exist — the ReferenceError was swallowed by the try, so the
    // pairs were set on every elevation INCLUDING this one but the DOM was never
